/**
 * Package discoverability rules (honua-io/honua-sdk-js#499, REQ-004).
 *
 * Two families are gated here:
 *
 *   - the split packages generated by `prepare-split-packages.mjs`, checked by
 *     `verify:split-packages`;
 *   - every package this repository publishes *from a committed manifest* —
 *     the root SDK, the MCP server, and the scaffold — checked by
 *     `verify:discoverability`.
 *
 * The second family exists because a published package with no keywords is
 * invisible in npm search no matter how good the SDK's own metadata is, and
 * that was measurably true of `@honua/mcp-server` (see
 * `docs/listings/npm-search-verification.md`). Keyword lists stay honest and
 * non-spammy: a package may only claim a discovery term it actually implements.
 */

const SHARED_KEYWORDS = ["gis", "geospatial", "maplibre", "typescript"];

/** Metadata npm shows on a package page; a published package must carry all of it. */
export const REQUIRED_PACKAGE_FIELDS = ["description", "keywords", "homepage", "repository", "bugs", "license"];

/** Minimum description length that can plausibly say what a package is. */
const MIN_DESCRIPTION_LENGTH = 40;

/**
 * Every package published from a committed manifest in this repository, with
 * the discovery terms it must carry. Split packages are generated and gated
 * separately below.
 */
export const PUBLISHED_PACKAGE_RULES = {
  "@honua/sdk-js": {
    manifest: "package.json",
    keywords: ["arcgis-migration", "ogc-api", "stac", "geocoding"],
    descriptionTerms: ["arcgis", "ogc api", "maplibre"],
  },
  "@honua/mcp-server": {
    manifest: "mcp/package.json",
    keywords: ["mcp", "model-context-protocol", "arcgis", "ogc-api"],
    descriptionTerms: ["mcp", "arcgis", "ogc api"],
  },
  "create-honua-app": {
    manifest: "packages/create-honua-app/package.json",
    keywords: ["scaffold", "starter", "create-app"],
    descriptionTerms: ["honua", "maplibre"],
  },
};

// Keep these requirements aligned with the generated package metadata in
// prepare-split-packages.mjs. They are intentionally package-specific: a
// geometry package should not claim to be an ArcGIS migration package, while
// every split package should remain discoverable as part of the Honua GIS /
// MapLibre family.
const SPLIT_PACKAGE_RULES = {
  "@honua/sdk": {
    keywords: ["arcgis", "ogc-api", "stac", "geocoding"],
    descriptionTerms: ["arcgis", "ogc api", "stac", "maplibre"],
  },
  "@honua/sdk-esri-compat": {
    keywords: ["arcgis-migration", "esri"],
    descriptionTerms: ["arcgis", "migration", "maplibre"],
  },
  "@honua/geometry": {
    keywords: ["geometry", "reprojection"],
    descriptionTerms: ["geometry"],
  },
  "@honua/react": {
    keywords: ["react", "map"],
    descriptionTerms: ["react", "map"],
  },
  "@honua/app-platform": {
    keywords: ["app-platform", "webmap"],
    descriptionTerms: ["application-platform", "workspace"],
  },
};

/** Keyword and description checks shared by both package families. */
function discoveryTermErrors(packageJson, rule) {
  const errors = [];
  const description = typeof packageJson?.description === "string" ? packageJson.description : "";
  const keywords = Array.isArray(packageJson?.keywords) ? packageJson.keywords : [];

  for (const keyword of SHARED_KEYWORDS) {
    if (!keywords.includes(keyword)) {
      errors.push(`missing shared keyword ${keyword}`);
    }
  }
  for (const keyword of rule.keywords) {
    if (!keywords.includes(keyword)) {
      errors.push(`missing package keyword ${keyword}`);
    }
  }
  if (keywords.length > 15) {
    errors.push(`keyword list has ${keywords.length} entries; maximum is 15`);
  }
  if (new Set(keywords).size !== keywords.length) {
    errors.push("keyword list repeats a keyword");
  }
  for (const term of rule.descriptionTerms) {
    if (!description.toLocaleLowerCase().includes(term)) {
      errors.push(`description is missing discovery term ${term}`);
    }
  }
  return errors;
}

export function splitPackageDiscoverabilityErrors(packageJson, expectedName) {
  const rule = SPLIT_PACKAGE_RULES[expectedName];
  const actualName = packageJson?.name ?? "<missing>";

  if (!rule) {
    return [`no discoverability rule exists for ${expectedName}`];
  }
  const errors = [];
  if (actualName !== expectedName) {
    errors.push(`package name is ${actualName}, expected ${expectedName}`);
  }
  errors.push(...discoveryTermErrors(packageJson, rule));
  return errors;
}

/**
 * Discoverability rules for a package published from a committed manifest.
 *
 * Stricter than the split-package rules on purpose: those manifests are
 * generated (so their fields cannot be forgotten), while these are hand-edited
 * and a missing `keywords`/`license`/`homepage` ships straight to the registry.
 */
export function publishedPackageDiscoverabilityErrors(packageJson, expectedName) {
  const rule = PUBLISHED_PACKAGE_RULES[expectedName];
  const actualName = packageJson?.name ?? "<missing>";

  if (!rule) {
    return [`no discoverability rule exists for ${expectedName}`];
  }
  const errors = [];
  if (actualName !== expectedName) {
    errors.push(`package name is ${actualName}, expected ${expectedName}`);
  }
  for (const field of REQUIRED_PACKAGE_FIELDS) {
    const value = packageJson?.[field];
    const empty = value === undefined || value === null || (Array.isArray(value) && value.length === 0);
    if (empty) {
      errors.push(`missing registry metadata field ${field}`);
    }
  }
  const description = typeof packageJson?.description === "string" ? packageJson.description : "";
  if (description.length > 0 && description.length < MIN_DESCRIPTION_LENGTH) {
    errors.push(
      `description is ${description.length} characters; at least ${MIN_DESCRIPTION_LENGTH} are needed to say what the package is`,
    );
  }
  errors.push(...discoveryTermErrors(packageJson, rule));
  return errors;
}
